import itertools
from pysat.solvers import Glucose3

n = 22
edges = {}
idx = 0
for i in range(n):
    for j in range(i+1, n):
        edges[(i,j)] = idx
        idx += 1

solver = Glucose3()

# For each 5-set: at least one blue edge
for subset in itertools.combinations(range(n), 5):
    clause = []
    for i in range(5):
        for j in range(i+1, 5):
            e = edges[(subset[i], subset[j])]
            clause.append(e+1)
    solver.add_clause(clause)

# For each 4-set: at least one red edge
for subset in itertools.combinations(range(n), 4):
    clause = []
    for i in range(4):
        for j in range(i+1, 4):
            e = edges[(subset[i], subset[j])]
            clause.append(-(e+1))
    solver.add_clause(clause)

result = solver.solve()
model = solver.get_model()

colors = []
for i in range(n):
    for j in range(i+1, n):
        e = edges[(i,j)]
        val = 1 if model[e] > 0 else 0
        colors.append(val)

print(f"Length: {len(colors)}")
print(f"Colors: {colors}")

# Double-check verification
red_ok = True
for subset in itertools.combinations(range(n), 5):
    all_red = True
    for i in range(5):
        for j in range(i+1, 5):
            e = edges[(subset[i], subset[j])]
            if colors[e] == 1:
                all_red = False
                break
        if not all_red:
            break
    if all_red:
        print(f"Red K5: {subset}")
        red_ok = False
        break

blue_ok = True
for subset in itertools.combinations(range(n), 4):
    all_blue = True
    for i in range(4):
        for j in range(i+1, 4):
            e = edges[(subset[i], subset[j])]
            if colors[e] == 0:
                all_blue = False
                break
        if not all_blue:
            break
    if all_blue:
        print(f"Blue K4: {subset}")
        blue_ok = False
        break

print(f"Red OK: {red_ok}, Blue OK: {blue_ok}")
